class UnionFind {
  #parent;
  #rank;
  #size;        // size of each set (only accurate at root)
  #components;  // number of disjoint sets

  constructor(n) {
    this.#parent     = Array.from({ length: n }, (_, i) => i);
    this.#rank       = new Array(n).fill(0);
    this.#size       = new Array(n).fill(1);
    this.#components = n;
  }

  // Path-compression find — O(α(n)) amortised
  find(x) {
    if (this.#parent[x] !== x) {
      this.#parent[x] = this.find(this.#parent[x]); // compress entire path
    }
    return this.#parent[x];
  }

  // Union by rank — O(α(n)) amortised
  // Returns true if a merge happened, false if already connected
  union(a, b) {
    const ra = this.find(a);
    const rb = this.find(b);
    if (ra === rb) return false;   // already in the same set — cycle detected!

    if (this.#rank[ra] < this.#rank[rb]) {
      this.#parent[ra] = rb;
      this.#size[rb] += this.#size[ra];
    } else if (this.#rank[ra] > this.#rank[rb]) {
      this.#parent[rb] = ra;
      this.#size[ra] += this.#size[rb];
    } else {
      // Equal rank: either direction works; increment winner's rank
      this.#parent[rb] = ra;
      this.#size[ra] += this.#size[rb];
      this.#rank[ra]++;
    }
    this.#components--;
    return true;
  }

  connected(a, b) { return this.find(a) === this.find(b); }
  count()         { return this.#components; }              // number of sets
  setSize(x)      { return this.#size[this.find(x)]; }     // size of x's set
}

// --- Demonstration ---
const uf = new UnionFind(7);
uf.union(0, 1);  // {0,1}, {2}, {3}, {4}, {5}, {6}
uf.union(1, 2);  // {0,1,2}, {3}, {4}, {5}, {6}
uf.union(3, 4);  // {0,1,2}, {3,4}, {5}, {6}
uf.union(4, 5);  // {0,1,2}, {3,4,5}, {6}

console.log(uf.connected(0, 2));  // true  (same set)
console.log(uf.connected(0, 3));  // false (different sets)
console.log(uf.count());          // 3 ({0,1,2}, {3,4,5}, {6})
console.log(uf.setSize(3));       // 3 (set {3,4,5} has 3 elements)

const alreadyConnected = uf.union(0, 2); // returns false — no merge
console.log(alreadyConnected);            // false

// --- Cycle Detection ---
function hasCycle(n, edges) {
  const uf = new UnionFind(n);
  for (const [u, v] of edges) {
    if (uf.connected(u, v)) return true; // u and v already connected => cycle
    uf.union(u, v);
  }
  return false;
}

console.log(hasCycle(4, [[0,1],[1,2],[2,3]]));        // false — it's a path (tree)
console.log(hasCycle(4, [[0,1],[1,2],[2,3],[3,0]])); // true  — forms a loop


// --- Kruskal's MST ---
function kruskalMST(numVertices, edges) {
  // edges format: [weight, u, v]
  const sorted = [...edges].sort((a, b) => a[0] - b[0]);
  const uf = new UnionFind(numVertices);
  const mst = [];
  let totalWeight = 0;

  for (const [w, u, v] of sorted) {
    if (!uf.connected(u, v)) {   // adding this edge does NOT create a cycle
      uf.union(u, v);
      mst.push([u, v, w]);
      totalWeight += w;
      if (mst.length === numVertices - 1) break; // V-1 edges = MST done
    }
  }

  const isSpanning = uf.count() === 1; // all vertices in one component
  return { mst, totalWeight, isSpanning };
}

// Graph: 4 vertices, 5 edges
// Edges: 0-1 (w=1), 0-2 (w=4), 1-2 (w=3), 1-3 (w=2), 2-3 (w=5)
const edges = [[1,0,1],[4,0,2],[3,1,2],[2,1,3],[5,2,3]];
const result = kruskalMST(4, edges);
console.log('MST edges:', result.mst);
// [[0,1,1], [1,3,2], [1,2,3]] — total weight 6
console.log('Total weight:', result.totalWeight); // 6
console.log('Is spanning:', result.isSpanning);   // true

// Iterative find with path splitting (avoids recursion stack overflow)
// Path splitting: each node points to its grandparent — same asymptotic complexity
function findIterative(parent, x) {
  while (parent[x] !== x) {
    parent[x] = parent[parent[x]]; // point to grandparent (path splitting)
    x = parent[x];
  }
  return x;
}

// Weighted Union-Find — tracks ratio between element and its root
// Example: currency conversion where we know A/B and B/C, want A/C
class WeightedUnionFind {
  #parent;
  #weight; // weight[x] = value[x] / value[find(x)]

  constructor(n) {
    this.#parent = Array.from({ length: n }, (_, i) => i);
    this.#weight = new Array(n).fill(1.0);
  }

  find(x) {
    if (this.#parent[x] !== x) {
      const root = this.find(this.#parent[x]);
      this.#weight[x] *= this.#weight[this.#parent[x]]; // chain weights
      this.#parent[x] = root;
    }
    return this.#parent[x];
  }

  // union: value[a] / value[b] = ratio
  union(a, b, ratio) {
    const ra = this.find(a);
    const rb = this.find(b);
    if (ra === rb) return;
    // After find, weight[a] = value[a]/value[ra], weight[b] = value[b]/value[rb]
    // We want value[ra]/value[rb] = ratio * weight[b] / weight[a]
    this.#parent[ra] = rb;
    this.#weight[ra] = ratio * this.#weight[b] / this.#weight[a];
  }

  // query: value[a] / value[b]
  query(a, b) {
    const ra = this.find(a);
    const rb = this.find(b);
    if (ra !== rb) return -1; // no relationship known
    return this.#weight[a] / this.#weight[b];
  }
}

// Example: a/b=2, b/c=3, so a/c=6
const wuf = new WeightedUnionFind(3); // 0=a, 1=b, 2=c
wuf.union(0, 1, 2.0); // a/b = 2
wuf.union(1, 2, 3.0); // b/c = 3
console.log(wuf.query(0, 2)); // 6.0 (a/c = a/b * b/c = 2*3)
console.log(wuf.query(2, 0)); // 0.1666... (c/a = 1/6)
